sign=1
for c in range(k):
    piv=None
    for r in range(c,k):
        if A[r][c] != 0:
            piv=r
            break
    if piv is None:
        print(0)
        raise SystemExit
    if piv != c:
        A[c],A[piv]=A[piv],A[c]
        sign *= -1
    pivot=A[c][c]
    for r in range(c+1,k):
        if A[r][c] == 0:
            continue
        factor=A[r][c] / pivot
        for j in range(c,k):
            A[r][j] -= factor * A[c][j]
ans=Fraction(sign,1)
for i in range(k):
    ans *= A[i][i]
print(ans)
print(ans.numerator)
print(ans.denominator)
